PRAGMA foreign_keys=ON;
CREATE TABLE admins (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,salt TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('owner','editor')),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE admin_sessions (id TEXT PRIMARY KEY,admin_id TEXT NOT NULL REFERENCES admins(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE movies (id TEXT PRIMARY KEY,title TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,synopsis TEXT NOT NULL DEFAULT '',poster TEXT NOT NULL DEFAULT '',banner TEXT NOT NULL DEFAULT '',release_year INTEGER NOT NULL,release_date TEXT NOT NULL DEFAULT '',cast_names TEXT NOT NULL DEFAULT '',director TEXT NOT NULL DEFAULT '',runtime INTEGER,seo_title TEXT NOT NULL DEFAULT '',meta_description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE categories (id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,slug TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE genres (id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE languages (id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE movie_categories (movie_id TEXT REFERENCES movies(id) ON DELETE CASCADE,category_id TEXT REFERENCES categories(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(movie_id,category_id));
CREATE TABLE movie_genres (movie_id TEXT REFERENCES movies(id) ON DELETE CASCADE,genre_id TEXT REFERENCES genres(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(movie_id,genre_id));
CREATE TABLE movie_languages (movie_id TEXT REFERENCES movies(id) ON DELETE CASCADE,language_id TEXT REFERENCES languages(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(movie_id,language_id));
CREATE TABLE rights_records (id TEXT PRIMARY KEY,movie_id TEXT NOT NULL UNIQUE REFERENCES movies(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','verified','revoked')),license TEXT NOT NULL,evidence_url TEXT NOT NULL,verified_by TEXT REFERENCES admins(id),verified_at TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE movie_files (id TEXT PRIMARY KEY,movie_id TEXT NOT NULL REFERENCES movies(id) ON DELETE CASCADE,resolution TEXT NOT NULL,codec TEXT NOT NULL,bytes INTEGER NOT NULL CHECK(bytes>0),audio TEXT NOT NULL,subtitles TEXT NOT NULL DEFAULT '',format TEXT NOT NULL,checksum TEXT NOT NULL DEFAULT '',enabled INTEGER NOT NULL DEFAULT 0,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE storage_providers (id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('external','r2')),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE download_mirrors (id TEXT PRIMARY KEY,file_id TEXT NOT NULL REFERENCES movie_files(id) ON DELETE CASCADE,provider_id TEXT REFERENCES storage_providers(id),label TEXT NOT NULL,url TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,expires_at INTEGER,health TEXT NOT NULL DEFAULT 'unknown',checked_at TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE screenshots (id TEXT PRIMARY KEY,movie_id TEXT NOT NULL REFERENCES movies(id) ON DELETE CASCADE,url TEXT NOT NULL,alt TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE download_events (id TEXT PRIMARY KEY,file_id TEXT REFERENCES movie_files(id) ON DELETE SET NULL,mirror_id TEXT REFERENCES download_mirrors(id) ON DELETE SET NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE copyright_reports (id TEXT PRIMARY KEY,movie_id TEXT REFERENCES movies(id) ON DELETE SET NULL,email TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE site_settings (id TEXT PRIMARY KEY,value TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE ad_placements (id TEXT PRIMARY KEY,label TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE audit_logs (id TEXT PRIMARY KEY,admin_id TEXT REFERENCES admins(id) ON DELETE SET NULL,action TEXT NOT NULL,target TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE auth_attempts (id TEXT PRIMARY KEY,count INTEGER NOT NULL,window_start INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX idx_movies_catalog ON movies(status,created_at DESC,id);
CREATE INDEX idx_movies_year ON movies(release_year,status);
CREATE INDEX idx_movies_title ON movies(title COLLATE NOCASE);
CREATE INDEX idx_files_movie ON movie_files(movie_id,enabled,resolution);
CREATE INDEX idx_mirrors_file ON download_mirrors(file_id,enabled);
CREATE INDEX idx_events_file ON download_events(file_id,created_at);
CREATE INDEX idx_sessions_expiry ON admin_sessions(expires_at);
CREATE INDEX idx_categories_movie ON movie_categories(category_id,movie_id);
CREATE INDEX idx_languages_movie ON movie_languages(language_id,movie_id);
